static inline double MODEL_DE_predict_one(const double* x) {
    double s = 0.0;
    for (int t = 0; t < MODEL_DE_NUM_TREES; t++) {
        int node = MODEL_DE_tree_roots[t];
        while (!MODEL_DE_nodes[node].is_leaf) {
            const MODEL_DE_node_t* n = &MODEL_DE_nodes[node];
            node = (x[n->feature] <= n->threshold) ? n->left : n->right;
        }
        s += MODEL_DE_nodes[node].value;
    }
    return s;
}

